package org.example.admin;

import org.apache.ibatis.annotations.Mapper;
import org.apache.ibatis.annotations.Param;

import java.time.LocalDateTime;

@Mapper
public interface ModerationCommandMapper {
    int hideIfPublished(@Param("postId") Long postId, @Param("actorId") Long actorId,
                        @Param("now") LocalDateTime now);

    int unhide(@Param("postId") Long postId);

    int changeRole(@Param("memberId") Long memberId, @Param("role") String role);
}

